using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Drawing;using System.Windows.Forms;using CircuitoStudio;
internal static class CableSizingTests {
static int n;static void Check(bool ok,string label){n++;if(!ok)throw new Exception(label);}static void Reject(Action a,string label){bool rejected=false;try{a();}catch(InvalidDataException){rejected=true;}Check(rejected,label);}
static Project Fixture(){var p=new Project();p.Source.LineVoltage=400;p.Source.ShortCircuitKA=6;var b=new Board{Id="Q",Voltage=400};var c=new Circuit{Id="C",Voltage=400,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",PowerKw=8*Math.Sqrt(3),PowerFactor=1,BreakerA=25,CableMm2=10,LengthM=10};c.Cable.AmpacityA=50;c.Cable.InstallationMethod="B1";c.Cable.Reference="BASE-QA-1";c.Protection.ConventionalTripA=36.25;c.Protection.LetThroughA2s=10000;c.Protection.DisconnectSeconds=.1;b.Circuits.Add(c);p.Boards.Add(b);var conditions=new CableFactorConditions{Arrangement="Ensaio: agrupados",AmbientC=40,GroupCount=2,LoadedConductors=3};var t=new CableFactorRow{Id="T40",Kind=CableFactorKind.Temperature,Material=ConductorMaterial.Copper,Insulation=CableInsulation.PVC,Installation="B1",AmbientC=40,LoadedConductors=3,Factor=.8,AmpacityReference="BASE-QA-1",Source="Sintético QA",DataVersion="2026.10"};var g=t.Copy();g.Id="G2";g.Kind=CableFactorKind.Grouping;g.AmbientC=0;g.GroupCount=2;g.Arrangement=conditions.Arrangement;g.Factor=.7;CableFactors.Apply(c,conditions,t,g);return p;}
static List<CableOption> Options(){return new[]{new[]{16d,68d},new[]{4d,32d},new[]{10d,50d},new[]{2.5,25d},new[]{6d,41d}}.Select(x=>new CableOption{Name="Ensaio "+x[0],Material="Cu",Insulation="PVC",Installation="B1",SectionMm2=x[0],IzA=x[1],ResistanceOhmKm=23.7/x[0],ReactanceOhmKm=0,Reference="BASE-QA-1"}).ToList();}
[STAThread]public static int Main(){string dir=Path.Combine(Path.GetTempPath(),"sizing-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{var p=Fixture();var c=p.Boards[0].Circuits[0];var options=Options();var result=CableSelection.Recommend(p,c,options);Check(result!=null&&result.Section==10,"smallest passing section sorted independently of table order");Check(Math.Abs(result.Iz.Value-28)<1e-10&&Math.Abs(result.Ib-20)<1e-10,"corrected ampacity and load");Check(result.Status=="Atende verificações locais","available local constraints pass");Check(c.CableMm2==10&&c.Cable.AmpacityA==50&&result.Cable==options[2],"recommendation references library and leaves project untouched");Check(result.Detail.Contains("BASE-QA-1")&&result.Detail.Contains("Menor seção")&&result.Detail.Contains("2026.10"),"traceable explanation uses conditions and source");
c.BreakerA=20;c.Protection.ConventionalTripA=29;Check(CableSelection.Recommend(p,c,options).Section==6,"lower protection allows 6 mm2");c.BreakerA=25;c.Protection.ConventionalTripA=42;Check(CableSelection.Recommend(p,c,options).Section==16,"I2 excludes section that passes In");c.Protection.ConventionalTripA=36.25;
var ten=options.Single(x=>x.SectionMm2==10);ten.Reference="OTHER";Check(CableSelection.Recommend(p,c,options).Section==16,"different ampacity reference cannot reuse factors");ten.Reference="BASE-QA-1";c.Cable.FactorsSnapshot.Temperature.MinSectionMm2=12;c.Cable.FactorsSnapshot.Grouping.MinSectionMm2=12;Check(CableSelection.Recommend(p,c,options).Section==16,"range applies to candidate section not original section");c.Cable.FactorsSnapshot.Temperature.MinSectionMm2=0;c.Cable.FactorsSnapshot.Grouping.MinSectionMm2=0;
c.LengthM=200;Check(CableSelection.Recommend(p,c,options).Section==16,"voltage drop forces larger section");c.VoltageDropLimitPercent=1;Check(CableSelection.Recommend(p,c,options)==null,"own voltage drop threshold may exclude entire table");c.LengthM=10;c.VoltageDropLimitPercent=null;
c.Protection.LetThroughA2s=2000000;Check(CableSelection.Recommend(p,c,options).Section==16,"thermal withstand rejects smaller candidates");c.Protection.LetThroughA2s=0;var pending=CableSelection.Recommend(p,c,options);Check(pending.Section==10&&pending.Status=="Dados incompletos"&&pending.Detail.Contains("Pendências"),"missing thermal data remains explicit pending preselection");c.Protection.LetThroughA2s=10000;
var snapshot=c.Cable.FactorsSnapshot;c.Cable.FactorsSnapshot=null;Check(CableSelection.Recommend(p,c,options)==null,"manual unreferenced factors cannot drive automatic sizing");c.Cable.FactorsSnapshot=snapshot;
Check(CableSelection.Recommend(p,c,new CableOption[0])==null,"empty table has no recommendation");Reject(delegate{CableSelection.Recommend(p,new Circuit(),options);},"foreign circuit rejected");var invalid=Options();invalid[0].IzA=double.NaN;Reject(delegate{CableSelection.Recommend(p,c,invalid);},"invalid table rejected before partial choice");
string artifacts=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-cabos");Directory.CreateDirectory(artifacts);p.Save(Path.Combine(artifacts,"origem.circuito"));CableSelection.ExportCsv(options,Path.Combine(artifacts,"cabos.csv"));using(var w=new StreamWriter(Path.Combine(artifacts,"avaliacoes.csv"))){w.WriteLine("Section;Iz;Ib;Drop;Status;Recommended");foreach(var option in options){var e=CableSelection.Evaluate(p,c,option);w.WriteLine(String.Join(";",new[]{e.Section.ToString("R",System.Globalization.CultureInfo.InvariantCulture),e.Iz.Value.ToString("R",System.Globalization.CultureInfo.InvariantCulture),e.Ib.ToString("R",System.Globalization.CultureInfo.InvariantCulture),e.Drop.ToString("R",System.Globalization.CultureInfo.InvariantCulture),e.Status,(option==result.Cable).ToString()}));}}
using(var form=new CableSelectionForm(p,c,Path.Combine(artifacts,"cabos.csv"))){form.CreateControl();typeof(CableSelectionForm).GetMethod("RecommendChoice",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,null);var grid=(DataGridView)typeof(CableSelectionForm).GetField("grid",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);Check(((CableEvaluation)grid.CurrentRow.DataBoundItem).Section==10,"editor highlights recommendation");Check(form.SelectedCable==null,"highlight alone does not commit project");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(10,10);form.Show();Application.DoEvents();typeof(CableSelectionForm).GetMethod("RecommendChoice",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,null);Check(((TextBox)typeof(CableSelectionForm).GetField("details",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form)).Text.Contains("Menor seção"),"display keeps recommendation explanation");using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(artifacts,"cabos.png"));}form.Hide();}}
c.PowerKw=0;c.BreakerA=0;Check(CableSelection.Recommend(p,c,options)==null,"no load no nominal protection avoids arbitrary sizing");Console.WriteLine("PASS: "+n+" cable-sizing assertions");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{Directory.Delete(dir,true);}}
}
